-- No characteristic at all, then one of each kind on its own.
CREATE FUNCTION f0(a INT) RETURNS INT RETURN a;
CREATE FUNCTION f1(a INT) RETURNS INT CONTAINS SQL RETURN a;
CREATE FUNCTION f2(a INT) RETURNS INT NO SQL RETURN a;
CREATE FUNCTION f3(a INT) RETURNS INT READS SQL DATA RETURN a;
CREATE FUNCTION f4(a INT) RETURNS INT SQL SECURITY DEFINER RETURN a;
CREATE FUNCTION f5(a INT) RETURNS INT COMMENT 'comment only' RETURN a;
CREATE FUNCTION f6(a INT) RETURNS INT COMMENT "double quoted" RETURN a;
CREATE PROCEDURE p0() SELECT 1;
CREATE PROCEDURE p1() MODIFIES SQL DATA SELECT 1;
CREATE PROCEDURE p2() LANGUAGE SQL SELECT 1;
CREATE PROCEDURE p3() SQL SECURITY INVOKER SELECT 1;
CREATE PROCEDURE p4() NOT DETERMINISTIC SELECT 1;
